storage_test_config <- function(profile="smoke") list(project=list(profile=profile,dataset_id="era5_mintemp"),paths=list(root=NULL))
test_that("storage profiles are isolated", { root<-file.path(tempdir(),"cds-datagrab"); s<-resolve_storage_paths(storage_test_config("smoke"),getwd(),root); p<-resolve_storage_paths(storage_test_config("production"),getwd(),root); expect_false(identical(s$dataset_root,p$dataset_root)); expect_true(grepl("data/smoke/era5_mintemp/daily$",s$daily_dir)); expect_true(grepl("data/production/era5_mintemp/weekly$",p$weekly_dir)); expect_false(file.exists(s$root_marker)) })
test_that("storage marker and directories are created safely", { root<-file.path(getwd(),"runtime",paste0("test-storage-",as.integer(Sys.time()))); s<-resolve_storage_paths(storage_test_config(),getwd(),root,create=TRUE); expect_true(file.exists(s$root_marker)); expect_true(dir.exists(s$daily_dir)); expect_true(assert_storage_target(s$daily_dir,s)); bad<-s; jsonlite::write_json(list(application="wrong"),s$root_marker,auto_unbox=TRUE); expect_error(assert_storage_target(s$daily_dir,bad),"marker") })
test_that("unsafe roots are rejected", { expect_error(resolve_storage_paths(storage_test_config(),getwd(),"/")); expect_error(resolve_storage_paths(storage_test_config(),getwd(),"/project/disease_ecology/NWScrewworm/data")); expect_error(resolve_storage_paths(storage_test_config(),getwd(),"../outside")) })
